/**
 * Spending-hierarchy types
 *
 * The two tiers above Category that the Spending Report rolls up through:
 *   Category (group_id) → CategoryGroup (Grouping) → ImportanceArea (Area of Importance)
 *
 * Importance attaches to the Grouping, not the individual category — a Grouping
 * has exactly one ImportanceArea. See docs/plans/2026-07-09-spending-report-design.md.
 */

/** Top tier — e.g. Essential / Priorities / Other. `sort_order` drives report order. */
export interface ImportanceArea {
	id: string;
	name: string;
	sort_order: number;
	family_id?: string;
	created_at?: string;
	updated_at?: string;
}

/** Middle tier — e.g. Everyday, Home, Transportation. Links up to one ImportanceArea. */
export interface CategoryGroup {
	id: string;
	name: string;
	importance_area_id: string;
	family_id?: string;
	created_at?: string;
	updated_at?: string;
}

