1	<script lang="ts">
2		/**
3		 * Spending Report page
4		 *
5		 * Rolls a year's Expenses up through Category → Grouping → Area of Importance
6		 * and renders the month-by-month grid (subtotals per Grouping and Importance,
7		 * a Year-to-Date column, Uncategorized at the bottom, Grand Total).
8		 *
9		 * All aggregation is the pure `buildSpendingReport` — this page only loads the
10		 * data and paints the grid. Design: docs/plans/2026-07-09-spending-report-design.md
11		 */
12	
13		import { onMount } from 'svelte';
14		import { resolve } from '$app/paths';
15		import { supabase } from '$lib/supabaseClient';
16		import { ExpenseService } from '$lib/services/ExpenseService';
17		import { CategoryService } from '$lib/services/CategoryService';
18		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
19		import { formatCurrency } from '$lib/utils/formatCurrency';
20		import {
21			buildSpendingReport,
22			type SpendingReport,
23			type SpendingCategory,
24			type Cell,
25			type ReportRow
26		} from '$lib/utils/spendingReport';
27		import {
28			buildSpendingDrilldownParams,
29			type DrilldownScope,
30			type DrilldownColumn
31		} from '$lib/utils/spendingDrilldown';
32		import type { CategoryGroup } from '$lib/types/Hierarchy';
33		import SpendingChart from '$lib/components/SpendingChart.svelte';
34		import type { Session } from '@supabase/supabase-js';
35	
36		let session: Session | null = $state(null);
37		let familyId: string | null = $state(null);
38		let year = $state(new Date().getFullYear());
39		let view = $state<'table' | 'chart'>('table');
40		let loading = $state(true);
41		let error: string | null = $state(null);
42		let report = $state<SpendingReport | null>(null);
43		// Kept in state (not just local to loadReport) so cell drill-down can expand a
44		// Grouping/Importance to its member category ids.
45		let categories = $state<SpendingCategory[]>([]);
46		let groups = $state<CategoryGroup[]>([]);
47	
48		onMount(async () => {
49			const { data } = await supabase.auth.getSession();
50			session = data.session;
51			if (!session) return;
52	
53			familyId = await getDefaultFamilyId();
54			if (!familyId) {
55				error = 'No family found. Please contact support.';
56				loading = false;
57				return;
58			}
59	
60			await loadReport();
61		});
62	
63		async function loadReport() {
64			if (!session?.user || !familyId) return;
65	
66			try {
67				loading = true;
68				error = null;
69	
70				const categoryService = new CategoryService(supabase);
71				const expenseService = new ExpenseService(supabase);
72	
73				// Seed the default hierarchy the first time a family opens the report
74				// (idempotent server-side), mirroring how categories self-initialize.
75				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
76				if (importanceAreas.length === 0) {
77					await categoryService.createDefaultHierarchy(familyId);
78					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
79				}
80	
81				const [loadedGroups, loadedCategories, expenses] = await Promise.all([
82					categoryService.getFamilyGroups(familyId),
83					categoryService.getFamilyCategories(familyId),
84					expenseService.getExpenses(session.user.id, {
85						startDate: `${year}-01-01`,
86						endDate: `${year}-12-31`
87					})
88				]);
89	
90				groups = loadedGroups;
91				categories = loadedCategories;
92				report = buildSpendingReport(expenses, loadedCategories, loadedGroups, importanceAreas, year);
93			} catch (err) {
94				console.error('Error loading spending report:', err);
95				error = err instanceof Error ? err.message : 'Failed to load the spending report';
96			} finally {
97				loading = false;
98			}
99		}
100	
101		function changeYear(delta: number) {
102			year += delta;
103			loadReport();
104		}
105	
106		/** A cell renders blank when no receipts fell in it, otherwise the amount. */
107		function cellText(cell: Cell): string {
108			return cell.count === 0 ? '' : formatCurrency(cell.amount);
109		}
110	
111		/**
112		 * The drill-down scope for a detail row: a real category when the row maps to
113		 * one (including a named-but-ungrouped Uncategorized row), otherwise the
114		 * "(No category)" catch-all drills to the uncategorized Expenses filter.
115		 */
116		function rowScope(row: ReportRow): DrilldownScope {
117			return row.categoryId
118				? { kind: 'category', categoryId: row.categoryId }
119				: { kind: 'uncategorized' };
120		}
121	
122		/**
123		 * The Expenses-view query a clicked cell links to, filtered to exactly what it
124		 * sums. Returns just the query string; the template builds the `/expenses?…`
125		 * template literal and wraps it in `resolve()` (both SvelteKit's typed `resolve`
126		 * and the no-navigation-without-resolve lint rule want that at the call site).
127		 */
128		function drilldownQuery(scope: DrilldownScope, column: DrilldownColumn): string {
129			return buildSpendingDrilldownParams(scope, column, year, categories, groups).toString();
130		}
131	
132		const hasData = $derived(report !== null && report.months.length > 0);
133	</script>
134	
135	<svelte:head>
136		<title>Spending — YFL Expense Tracker</title>
137	</svelte:head>
138	
139	<div class="spending-page">
140		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
141			<div>
142				<h1 class="mb-2 text-2xl font-bold">Spending</h1>
143				<p class="text-gray-600">
144					Your expenses by Area of Importance, Grouping, and Category. Amounts in CAD.
145				</p>
146			</div>
147			<div class="flex items-center gap-4">
148				<div class="inline-flex overflow-hidden rounded border border-gray-300" role="group">
149					<button
150						type="button"
151						class="px-3 py-1 text-sm {view === 'table'
152							? 'bg-indigo-600 text-white'
153							: 'bg-white text-gray-700 hover:bg-gray-100'}"
154						aria-pressed={view === 'table'}
155						onclick={() => (view = 'table')}
156					>
157						Table
158					</button>
159					<button
160						type="button"
161						class="border-l border-gray-300 px-3 py-1 text-sm {view === 'chart'
162							? 'bg-indigo-600 text-white'
163							: 'bg-white text-gray-700 hover:bg-gray-100'}"
164						aria-pressed={view === 'chart'}
165						onclick={() => (view = 'chart')}
166					>
167						Chart
168					</button>
169				</div>
170				<div class="flex items-center gap-2">
171					<button
172						type="button"
173						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
174						onclick={() => changeYear(-1)}
175						aria-label="Previous year"
176					>
177						←
178					</button>
179					<span class="min-w-16 text-center text-lg font-semibold" aria-live="polite">{year}</span>
180					<button
181						type="button"
182						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
183						onclick={() => changeYear(1)}
184						aria-label="Next year"
185					>
186						→
187					</button>
188				</div>
189			</div>
190		</div>
191	
192		{#if loading}
193			<div class="flex items-center justify-center p-8 text-gray-500">Loading spending report…</div>
194		{:else if error}
195			<div class="rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
196		{:else if !hasData}
197			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
198				No expenses recorded for {year}.
199			</div>
200		{:else if report}
201			{#if report.missingAmountCount > 0}
202				<p class="mb-3 text-sm text-yellow-700">
203					⚠ {report.missingAmountCount} receipt{report.missingAmountCount === 1 ? '' : 's'} in {year}
204					{report.missingAmountCount === 1 ? 'has' : 'have'} no amount and count as $0. Open them on the
205					Receipts page to fix.
206				</p>
207			{/if}
208	
209			{#snippet nameCell(name: string)}
210				<!-- Long category names truncate to one line; the full name shows on hover. -->
211				<span class="block max-w-64 truncate" title={name}>{name}</span>
212			{/snippet}
213	
214			{#snippet valueCells(row: ReportRow, scope: DrilldownScope)}
215				{#each row.cells as cell, i (cell)}
216					<td class="px-3 py-1 text-right tabular-nums">
217						{#if cell.count > 0}
218							<!-- months run Jan → maxMonth contiguously, so column i is month i+1 -->
219							<a
220								class="hover:text-indigo-600 hover:underline"
221								href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'month', month: i + 1 })}`)}
222								title="View these expenses">{cellText(cell)}</a
223							>
224						{/if}
225					</td>
226				{/each}
227				<td class="px-3 py-1 text-right font-semibold tabular-nums">
228					{#if row.ytd.count > 0}
229						<a
230							class="hover:text-indigo-600 hover:underline"
231							href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'ytd' })}`)}
232							title="View these expenses">{cellText(row.ytd)}</a
233						>
234					{/if}
235				</td>
236			{/snippet}
237	
238			{#if view === 'table'}
239				<div class="overflow-x-auto">
240					<table class="min-w-full border-collapse text-sm">
241						<thead>
242							<tr class="border-b-2 border-gray-300 bg-gray-50 text-gray-700">
243								<th class="px-3 py-2 text-left font-semibold">Category</th>
244								{#each report.monthLabels as label (label)}
245									<th class="px-3 py-2 text-right font-semibold">{label}</th>
246								{/each}
247								<th class="px-3 py-2 text-right font-semibold">Year to Date</th>
248							</tr>
249						</thead>
250						<tbody>
251							{#each report.importances as importance (importance.name)}
252								<tr class="bg-indigo-100 font-semibold text-indigo-900">
253									<td class="px-3 py-1" colspan={report.months.length + 2}>{importance.name}</td>
254								</tr>
255								{#each importance.groups as group (group.name)}
256									{#each group.rows as row (row.name)}
257										<tr class="border-b border-gray-100">
258											<td class="px-3 py-1 pl-8">{@render nameCell(row.name)}</td>
259											{@render valueCells(row, rowScope(row))}
260										</tr>
261									{/each}
262									<tr class="border-b border-gray-200 bg-gray-100 font-medium">
263										<td class="px-3 py-1 pl-6">{group.name} Total</td>
264										{@render valueCells(group.subtotal, {
265											kind: 'group',
266											groupId: group.id ?? ''
267										})}
268									</tr>
269								{/each}
270								<tr class="border-b-2 border-indigo-200 bg-indigo-50 font-semibold">
271									<td class="px-3 py-1">{importance.name} Total</td>
272									{@render valueCells(importance.subtotal, {
273										kind: 'importance',
274										importanceId: importance.id
275									})}
276								</tr>
277							{/each}
278	
279							{#if report.uncategorized}
280								<tr class="bg-amber-100 font-semibold text-amber-900">
281									<td class="px-3 py-1" colspan={report.months.length + 2}>Uncategorized</td>
282								</tr>
283								{#each report.uncategorized.rows as row (row.name)}
284									<tr class="border-b border-gray-100">
285										<td class="px-3 py-1 pl-8">{@render nameCell(row.name)}</td>
286										{@render valueCells(row, rowScope(row))}
287									</tr>
288								{/each}
289								<tr class="border-b-2 border-amber-200 bg-amber-50 font-semibold">
290									<td class="px-3 py-1">Uncategorized Total</td>
291									{@render valueCells(report.uncategorized.subtotal, { kind: 'uncategorized' })}
292								</tr>
293							{/if}
294	
295							<tr class="border-t-2 border-gray-400 bg-gray-200 font-bold">
296								<td class="px-3 py-2">Grand Total</td>
297								{@render valueCells(report.grandTotal, { kind: 'grandTotal' })}
298							</tr>
299						</tbody>
300					</table>
301				</div>
302			{:else}
303				<SpendingChart {report} />
304			{/if}
305		{/if}
306	</div>
