1	/**
2	 * CategoryService
3	 *
4	 * Service for managing family expense categories
5	 * Specification: #{#exp3a} - Family Category Management
6	 * Authority: developer
7	 * Priority: High
8	 *
9	 * Key Principles:
10	 * - Categories are scoped to families (family_id), not individual users
11	 * - All active family members can view and use the same categories
12	 * - New families receive default categories on creation
13	 * - Category names must be unique per family (case-insensitive)
14	 * - Categories support optional color coding
15	 */
16	
17	import type { SupabaseClient } from '@supabase/supabase-js';
18	import type { Category } from '$lib/types/Category';
19	import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';
20	
21	/**
22	 * Category data structure — single source of truth lives in $lib/types/Category.
23	 * Re-exported here so existing `import type { Category } from './CategoryService'`
24	 * consumers keep working.
25	 */
26	export type { Category } from '$lib/types/Category';
27	
28	/**
29	 * Default category definition
30	 */
31	interface DefaultCategory {
32		name: string;
33		color: string;
34	}
35	
36	/**
37	 * Fields that updateCategory writes to a category row.
38	 * `color` is only included when the caller explicitly provides one.
39	 */
40	interface CategoryUpdateData {
41		name: string;
42		updated_at: string;
43		color?: string | null;
44	}
45	
46	/**
47	 * Default categories for new families
48	 * Specification: #{#exp3a} Requirement 3
49	 *
50	 * Updated with user's custom category list
51	 * Families can replace, delete, or ignore these categories as needed
52	 */
53	const DEFAULT_CATEGORIES: DefaultCategory[] = [
54		{ name: 'Alcohol', color: '#DC2626' },
55		{ name: 'Kids - Allowance', color: '#F97316' },
56		{ name: 'Kids - Activities', color: '#FB923C' },
57		{ name: 'Banking and Tracking Fees', color: '#64748B' },
58		{ name: 'Birthday Expenses', color: '#EC4899' },
59		{ name: 'Car - Other Expenses', color: '#0EA5E9' },
60		{ name: 'Car - Repairs & Maintenance', color: '#06B6D4' },
61		{ name: 'Car - Insurance', color: '#3B82F6' },
62		{ name: 'Car - Gas', color: '#2563EB' },
63		{ name: 'Car - Parking', color: '#1D4ED8' },
64		{ name: 'Clothes', color: '#A855F7' },
65		{ name: 'Coffee and Tea', color: '#92400E' },
66		{ name: 'Credit Card Fees', color: '#78716C' },
67		{ name: 'Dental', color: '#EF4444' },
68		{ name: 'Donation', color: '#10B981' },
69		{ name: 'Entertainment', color: '#8B5CF6' },
70		{ name: 'Garden', color: '#22C55E' },
71		{ name: 'Gifts', color: '#F472B6' },
72		{ name: 'Groceries', color: '#10B981' },
73		{ name: 'House Insurance', color: '#6366F1' },
74		{ name: 'House Maintenance and Repairs', color: '#7C3AED' },
75		{ name: 'Household goods', color: '#8B5CF6' },
76		{ name: 'Income taxes', color: '#B91C1C' },
77		{ name: 'Investments', color: '#059669' },
78		{ name: 'Meals and Drinks Out', color: '#F59E0B' },
79		{ name: 'Mortgage', color: '#4F46E5' },
80		{ name: 'Personal Care', color: '#D946EF' },
81		{ name: 'Pharmacy and Medical Tax Deductible', color: '#EF4444' },
82		{
83			name: 'Therapy Tax Deductible (Physiotherapy, Psychotherapy, Acupuncture, and Chiropractor)',
84			color: '#DC2626'
85		},
86		{ name: 'Therapy Not Tax Deductible (Massage, unregistered therapists)', color: '#F87171' },
87		{ name: 'Postage and shipping costs', color: '#94A3B8' },
88		{ name: 'Property Taxes', color: '#991B1B' },
89		{ name: 'Renovation Expenses', color: '#9333EA' },
90		{ name: 'Rental Properties', color: '#6366F1' },
91		{ name: 'School fees (including Tutors)', color: '#FB923C' },
92		{ name: 'Sports and Fitness', color: '#14B8A6' },
93		{ name: 'Travel - Accommodations', color: '#0D9488' },
94		{ name: 'Travel - Airfare', color: '#0891B2' },
95		{ name: 'Travel - Entertainment', color: '#06B6D4' },
96		{ name: 'Travel - Food', color: '#22D3EE' },
97		{ name: 'Travel - Transportation', color: '#67E8F9' },
98		{ name: 'University expenses', color: '#C026D3' },
99		{ name: 'Utilities', color: '#6366F1' }
100	];
101	
102	/**
103	 * CategoryService Class
104	 * Handles all category-related operations
105	 */
106	export class CategoryService {
107		private supabase: SupabaseClient;
108	
109		constructor(supabase: SupabaseClient) {
110			this.supabase = supabase;
111		}
112	
113		/**
114		 * Get list of default categories
115		 * Specification: #{#exp3a} Requirement 3
116		 */
117		getDefaultCategoryList(): DefaultCategory[] {
118			return DEFAULT_CATEGORIES;
119		}
120	
121		/**
122		 * Get all categories for a family
123		 *
124		 * @param familyId - Family ID to filter categories
125		 * @returns Array of categories ordered by name
126		 *
127		 * Specification: #{#exp3a} Requirement 1
128		 */
129		async getFamilyCategories(familyId: string): Promise<Category[]> {
130			// Requirement: Family ID validation
131			if (!familyId) {
132				throw new Error('Family ID is required');
133			}
134	
135			// Query categories filtered by family_id
136			// RLS policies ensure user is an active member of this family
137			const { data, error } = await this.supabase
138				.from('categories')
139				.select('*')
140				.eq('family_id', familyId)
141				.order('name', { ascending: true });
142	
143			if (error) {
144				throw new Error(error.message);
145			}
146	
147			return data || [];
148		}
149	
150		/**
151		 * DEPRECATED: Use getFamilyCategories instead
152		 * @deprecated This method is maintained for backward compatibility
153		 */
154		async getUserCategories(userId: string): Promise<Category[]> {
155			console.warn('getUserCategories is deprecated. Use getFamilyCategories instead.');
156	
157			// Get user's default family and fetch categories for that family
158			const { data: familyMember, error: fmError } = await this.supabase
159				.from('family_members')
160				.select('family_id')
161				.eq('user_id', userId)
162				.eq('is_default', true)
163				.eq('status', 'active')
164				.single();
165	
166			if (fmError || !familyMember) {
167				throw new Error('Could not find default family for user');
168			}
169	
170			return this.getFamilyCategories(familyMember.family_id);
171		}
172	
173		/**
174		 * Get the spending-hierarchy Areas of Importance for a family, ordered by
175		 * sort_order (the report's top-tier order).
176		 */
177		async getFamilyImportanceAreas(familyId: string): Promise<ImportanceArea[]> {
178			if (!familyId) {
179				throw new Error('Family ID is required');
180			}
181	
182			const { data, error } = await this.supabase
183				.from('importance_areas')
184				.select('*')
185				.eq('family_id', familyId)
186				.order('sort_order', { ascending: true });
187	
188			if (error) {
189				throw new Error(error.message);
190			}
191	
192			return data || [];
193		}
194	
195		/**
196		 * Get the spending-hierarchy Groupings for a family. Each group carries its
197		 * `importance_area_id`.
198		 */
199		async getFamilyGroups(familyId: string): Promise<CategoryGroup[]> {
200			if (!familyId) {
201				throw new Error('Family ID is required');
202			}
203	
204			const { data, error } = await this.supabase
205				.from('category_groups')
206				.select('*')
207				.eq('family_id', familyId)
208				.order('name', { ascending: true });
209	
210			if (error) {
211				throw new Error(error.message);
212			}
213	
214			return data || [];
215		}
216	
217		/**
218		 * Seed the default spending hierarchy (Importance areas + Groupings, and map
219		 * the default categories into them) for a family. Idempotent server-side —
220		 * safe to call whenever a family has no hierarchy yet. Mirrors the
221		 * lazy-initialization pattern used for default categories.
222		 */
223		async createDefaultHierarchy(familyId: string): Promise<void> {
224			if (!familyId) {
225				throw new Error('Family ID is required');
226			}
227	
228			const { error } = await this.supabase.rpc('create_default_hierarchy', {
229				p_family_id: familyId
230			});
231	
232			if (error) {
