/**
 * CategoryService
 *
 * Service for managing family expense categories
 * Specification: #{#exp3a} - Family Category Management
 * Authority: developer
 * Priority: High
 *
 * Key Principles:
 * - Categories are scoped to families (family_id), not individual users
 * - All active family members can view and use the same categories
 * - New families receive default categories on creation
 * - Category names must be unique per family (case-insensitive)
 * - Categories support optional color coding
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type { Category } from '$lib/types/Category';
import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';

/**
 * Category data structure — single source of truth lives in $lib/types/Category.
 * Re-exported here so existing `import type { Category } from './CategoryService'`
 * consumers keep working.
 */
export type { Category } from '$lib/types/Category';

/**
 * Default category definition
 */
interface DefaultCategory {
	name: string;
	color: string;
}

/**
 * Fields that updateCategory writes to a category row.
 * `color` is only included when the caller explicitly provides one.
 */
interface CategoryUpdateData {
	name: string;
	updated_at: string;
	color?: string | null;
}

/**
 * Default categories for new families
 * Specification: #{#exp3a} Requirement 3
 *
 * Updated with user's custom category list
 * Families can replace, delete, or ignore these categories as needed
 */
const DEFAULT_CATEGORIES: DefaultCategory[] = [
	{ name: 'Alcohol', color: '#DC2626' },
	{ name: 'Kids - Allowance', color: '#F97316' },
	{ name: 'Kids - Activities', color: '#FB923C' },
	{ name: 'Banking and Tracking Fees', color: '#64748B' },
	{ name: 'Birthday Expenses', color: '#EC4899' },
	{ name: 'Car - Other Expenses', color: '#0EA5E9' },
	{ name: 'Car - Repairs & Maintenance', color: '#06B6D4' },
	{ name: 'Car - Insurance', color: '#3B82F6' },
	{ name: 'Car - Gas', color: '#2563EB' },
	{ name: 'Car - Parking', color: '#1D4ED8' },
	{ name: 'Clothes', color: '#A855F7' },
	{ name: 'Coffee and Tea', color: '#92400E' },
	{ name: 'Credit Card Fees', color: '#78716C' },
	{ name: 'Dental', color: '#EF4444' },
	{ name: 'Donation', color: '#10B981' },
	{ name: 'Entertainment', color: '#8B5CF6' },
	{ name: 'Garden', color: '#22C55E' },
	{ name: 'Gifts', color: '#F472B6' },
	{ name: 'Groceries', color: '#10B981' },
	{ name: 'House Insurance', color: '#6366F1' },
	{ name: 'House Maintenance and Repairs', color: '#7C3AED' },
	{ name: 'Household goods', color: '#8B5CF6' },
	{ name: 'Income taxes', color: '#B91C1C' },
	{ name: 'Investments', color: '#059669' },
	{ name: 'Meals and Drinks Out', color: '#F59E0B' },
	{ name: 'Mortgage', color: '#4F46E5' },
	{ name: 'Personal Care', color: '#D946EF' },
	{ name: 'Pharmacy and Medical Tax Deductible', color: '#EF4444' },
	{
		name: 'Therapy Tax Deductible (Physiotherapy, Psychotherapy, Acupuncture, and Chiropractor)',
		color: '#DC2626'
	},
	{ name: 'Therapy Not Tax Deductible (Massage, unregistered therapists)', color: '#F87171' },
	{ name: 'Postage and shipping costs', color: '#94A3B8' },
	{ name: 'Property Taxes', color: '#991B1B' },
	{ name: 'Renovation Expenses', color: '#9333EA' },
	{ name: 'Rental Properties', color: '#6366F1' },
	{ name: 'School fees (including Tutors)', color: '#FB923C' },
	{ name: 'Sports and Fitness', color: '#14B8A6' },
	{ name: 'Travel - Accommodations', color: '#0D9488' },
	{ name: 'Travel - Airfare', color: '#0891B2' },
	{ name: 'Travel - Entertainment', color: '#06B6D4' },
	{ name: 'Travel - Food', color: '#22D3EE' },
	{ name: 'Travel - Transportation', color: '#67E8F9' },
	{ name: 'University expenses', color: '#C026D3' },
	{ name: 'Utilities', color: '#6366F1' }
];

/**
 * CategoryService Class
 * Handles all category-related operations
 */
export class CategoryService {
	private supabase: SupabaseClient;

	constructor(supabase: SupabaseClient) {
		this.supabase = supabase;
	}

	/**
	 * Get list of default categories
	 * Specification: #{#exp3a} Requirement 3
	 */
	getDefaultCategoryList(): DefaultCategory[] {
		return DEFAULT_CATEGORIES;
	}

	/**
	 * Get all categories for a family
	 *
	 * @param familyId - Family ID to filter categories
	 * @returns Array of categories ordered by name
	 *
	 * Specification: #{#exp3a} Requirement 1
	 */
	async getFamilyCategories(familyId: string): Promise<Category[]> {
		// Requirement: Family ID validation
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		// Query categories filtered by family_id
		// RLS policies ensure user is an active member of this family
		const { data, error } = await this.supabase
			.from('categories')
			.select('*')
			.eq('family_id', familyId)
			.order('name', { ascending: true });

		if (error) {
			throw new Error(error.message);
		}

		return data || [];
	}

	/**
	 * DEPRECATED: Use getFamilyCategories instead
	 * @deprecated This method is maintained for backward compatibility
	 */
	async getUserCategories(userId: string): Promise<Category[]> {
		console.warn('getUserCategories is deprecated. Use getFamilyCategories instead.');

		// Get user's default family and fetch categories for that family
		const { data: familyMember, error: fmError } = await this.supabase
			.from('family_members')
			.select('family_id')
			.eq('user_id', userId)
			.eq('is_default', true)
			.eq('status', 'active')
			.single();

		if (fmError || !familyMember) {
			throw new Error('Could not find default family for user');
		}

		return this.getFamilyCategories(familyMember.family_id);
	}

	/**
	 * Get the spending-hierarchy Areas of Importance for a family, ordered by
	 * sort_order (the report's top-tier order).
	 */
	async getFamilyImportanceAreas(familyId: string): Promise<ImportanceArea[]> {
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		const { data, error } = await this.supabase
			.from('importance_areas')
			.select('*')
			.eq('family_id', familyId)
			.order('sort_order', { ascending: true });

		if (error) {
			throw new Error(error.message);
		}

		return data || [];
	}

	/**
	 * Get the spending-hierarchy Groupings for a family. Each group carries its
	 * `importance_area_id`.
	 */
	async getFamilyGroups(familyId: string): Promise<CategoryGroup[]> {
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		const { data, error } = await this.supabase
			.from('category_groups')
			.select('*')
			.eq('family_id', familyId)
			.order('name', { ascending: true });

		if (error) {
			throw new Error(error.message);
		}

		return data || [];
	}

	/**
	 * Seed the default spending hierarchy (Importance areas + Groupings, and map
	 * the default categories into them) for a family. Idempotent server-side —
	 * safe to call whenever a family has no hierarchy yet. Mirrors the
	 * lazy-initialization pattern used for default categories.
	 */
	async createDefaultHierarchy(familyId: string): Promise<void> {
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		const { error } = await this.supabase.rpc('create_default_hierarchy', {
			p_family_id: familyId
		});

		if (error) {
			throw new Error(error.message);
		}
	}

	/**
	 * Create default categories for a new family
	 *
	 * @param familyId - Family ID to create categories for
	 *
	 * Specification: #{#exp3a} Requirements 2 & 3
	 */
	async createDefaultCategories(familyId: string): Promise<void> {
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		// Only create if family has no categories
		const existing = await this.getFamilyCategories(familyId);
		if (existing.length > 0) {
			return; // Family already has categories
		}

		// Insert default categories directly using the DEFAULT_CATEGORIES constant
		// This ensures we always use the latest category list
		const categoriesToInsert = DEFAULT_CATEGORIES.map((cat) => ({
			family_id: familyId,
			name: cat.name,
			color: cat.color
		}));

		const { error } = await this.supabase.from('categories').insert(categoriesToInsert);

		// Ignore unique constraint violations (23505) - categories already exist
		if (error && error.code !== '23505') {
			throw new Error(error.message);
		}
	}

	/**
	 * Create a new custom category
	 *
	 * @param familyId - Family ID
	 * @param name - Category name
	 * @param color - Optional hex color code (#RRGGBB)
	 * @returns Created category
	 *
	 * Specification: #{#exp3a} Requirements 4, 7, 8
	 */
	async createCategory(familyId: string, name: string, color?: string): Promise<Category> {
		// Validation
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		if (!name || name.trim() === '') {
			throw new Error('Category name is required');
		}

		if (name.length > 100) {
			throw new Error('Category name must be 100 characters or less');
		}

		// Validate color format if provided
		if (color !== undefined && color !== null && color !== '') {
			if (!this.isValidHexColor(color)) {
				throw new Error('Invalid color format. Use hex format: #RRGGBB');
			}
		}

		// Insert category
		const { data, error } = await this.supabase
			.from('categories')
			.insert({
				family_id: familyId,
				name: name.trim(),
				color: color || null
			})
			.select()
			.single();

		if (error) {
			// Handle unique constraint violation
			if (error.code === '23505') {
				throw new Error('A category with this name already exists in this family');
			}
			throw new Error(error.message);
		}

		return data;
	}

	/**
	 * Update an existing category
	 *
	 * @param categoryId - Category ID to update
	 * @param name - New category name
	 * @param color - New color (optional)
	 * @returns Updated category
	 *
	 * Specification: #{#exp3a} Requirement 5
	 */
	async updateCategory(categoryId: string, name: string, color?: string): Promise<Category> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		if (!name || name.trim() === '') {
			throw new Error('Category name is required');
		}

		if (name.length > 100) {
			throw new Error('Category name must be 100 characters or less');
		}

		// Validate color format if provided
		if (color !== undefined && color !== null && color !== '') {
			if (!this.isValidHexColor(color)) {
				throw new Error('Invalid color format. Use hex format: #RRGGBB');
			}
		}

		const updateData: CategoryUpdateData = {
			name: name.trim(),
			updated_at: new Date().toISOString()
		};

		if (color !== undefined) {
			updateData.color = color;
		}

		const { data, error } = await this.supabase
			.from('categories')
			.update(updateData)
			.eq('id', categoryId)
			.select()
			.single();

		if (error) {
			// Handle unique constraint violation
			if (error.code === '23505') {
				throw new Error('A category with this name already exists in this family');
			}
			throw new Error(error.message);
		}

		return data;
	}

	/**
	 * Delete a category
	 *
	 * @param categoryId - Category ID to delete
	 *
	 * Specification: #{#exp3a} Requirement 6
	 */
	async deleteCategory(categoryId: string): Promise<void> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		const { error } = await this.supabase.from('categories').delete().eq('id', categoryId);

		if (error) {
			throw new Error(error.message);
		}
	}

	/**
	 * Check if a category has associated expenses
	 *
	 * @param categoryId - Category ID to check
	 * @returns True if category has expenses, false otherwise
	 *
	 * Specification: #{#exp3a} Requirement 6
	 */
	async categoryHasExpenses(categoryId: string): Promise<boolean> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		const { data, error } = await this.supabase
			.from('expense_categories')
			.select('receipt_id')
			.eq('category_id', categoryId);

		if (error) {
			throw new Error(error.message);
		}

		return data && data.length > 0;
	}

	/**
	 * Validate hex color format
	 *
	 * @param color - Color string to validate
	 * @returns True if valid hex color
	 *
	 * Specification: #{#exp3a} Requirement 8
	 */
	private isValidHexColor(color: string): boolean {
		const hexColorRegex = /^#[0-9A-Fa-f]{6}$/;
		return hexColorRegex.test(color);
	}
}

