149			const maxIndex = filteredCategories.length - 1;
150	
151			switch (event.key) {
152				case 'ArrowDown':
153					event.preventDefault();
154					selectedIndex = selectedIndex < maxIndex ? selectedIndex + 1 : selectedIndex;
155					break;
156	
157				case 'ArrowUp':
158					event.preventDefault();
159					selectedIndex = selectedIndex > 0 ? selectedIndex - 1 : selectedIndex;
160					break;
161	
162				case 'Enter':
163					event.preventDefault();
164					if (filteredCategories.length > 0 && selectedIndex >= 0) {
165						selectCategory(filteredCategories[selectedIndex]);
166					}
167					break;
168	
169				case 'Escape':
170					event.preventDefault();
171					closeDropdown();
172					break;
173			}
174		}
175	
176		/**
177		 * Handle click outside to close dropdown
178		 * #{#exp2a} Criterion 9
179		 */
180		function handleClickOutside(event: MouseEvent) {
181			const target = event.target as Node | null;
182			// Svelte 5 flushes state synchronously after a delegated click handler, so a
183			// click that toggles the dropdown's own content (e.g. "Create new category…")
184			// detaches its target from the DOM before this document-level listener runs.
185			// A detached target is never a genuine outside click — bail so we don't close.
186			if (target && !target.isConnected) return;
187			if (dropdownElement && !dropdownElement.contains(target)) {
188				closeDropdown();
189			}
190		}
191	
192		/**
193		 * Setup click outside listener
194		 */
195		onMount(() => {
196			document.addEventListener('click', handleClickOutside);
197			return () => {
198				document.removeEventListener('click', handleClickOutside);
199			};
200		});
201	
202		/**
203		 * Handle create new category click
204		 * #{#exp3b} Criterion 2 - Show inline input field
205		 */
206		function handleCreateCategory() {
207			isInCreationMode = true;
208			creationError = null;
209			newCategoryName = '';
210			newCategoryColor = '';
211	
212			// Auto-focus name input
213			setTimeout(() => {
214				nameInputElement?.focus();
215			}, 0);
216		}
217	
218		/**
219		 * Cancel inline creation mode
220		 * #{#exp3b} Criterion 3
221		 */
222		function cancelInlineCreation() {
223			isInCreationMode = false;
224			newCategoryName = '';
225			newCategoryColor = '';
226			creationError = null;
227		}
228	
229		/**
230		 * Validate new category name
231		 * #{#exp3b} Criteria 8, 9, 10
232		 */
233		function validateNewCategory(name: string): { isValid: boolean; error: string | null } {
234			const trimmedName = name.trim();
235	
236			// Criterion 9: Empty name validation
237			if (trimmedName.length === 0) {
238				return { isValid: false, error: 'Category name required' };
239			}
240	
241			// Criterion 10: Max length validation
242			if (trimmedName.length > 100) {
243				return { isValid: false, error: 'Category name must be 100 characters or less' };
244			}
245	
246			// Criterion 8: Duplicate validation (case-insensitive)
247			const isDuplicate = categories.some(
248				(cat) => cat.name.toLowerCase() === trimmedName.toLowerCase()
249			);
250			if (isDuplicate) {
251				return { isValid: false, error: 'Category already exists' };
252			}
253	
254			return { isValid: true, error: null };
255		}
256	
257		/**
258		 * Create new category
259		 * #{#exp3b} Criteria 5, 6, 7
260		 */
261		async function createNewCategory() {
262			// Validate input
263			const validation = validateNewCategory(newCategoryName);
264			if (!validation.isValid) {
265				creationError = validation.error;
266				return;
267			}
268	
269			// Dispatch event to parent with new category data
270			// Parent will handle CategoryService.createCategory() call
271			onCreateNewCategory?.({
272				name: newCategoryName.trim(),
273				color: newCategoryColor || null
274			});
275	
276			// Reset state
277			cancelInlineCreation();
278		}
279	
