281		 * Handle keyboard navigation in creation form
282		 */
283		function handleCreationKeyDown(event: KeyboardEvent) {
284			if (event.key === 'Enter') {
285				event.preventDefault();
286				createNewCategory();
287			} else if (event.key === 'Escape') {
288				event.preventDefault();
289				cancelInlineCreation();
290			}
291		}
