/**
 * hierarchyTree — shape the flat spending-hierarchy tables into the nested tree
 * the hierarchy editor renders.
 *
 * Input is the three family-scoped tables loaded separately (Areas of Importance,
 * Groupings, Categories). Output is Importance → Grouping → Category nested for
 * display, plus a flat `unassigned` bucket of categories with no `group_id`
 * (the ones that fall to "Uncategorized" in the report and are the whole reason
 * the editor exists).
 *
 * Pure and unit-tested, in the style of buildSpendingReport — the editor page
 * only loads data, renders this tree, and calls the mutation service.
 *
 * Ordering mirrors the report: Importance by `sort_order`, Groupings alphabetical
 * within an Importance, Categories alphabetical within a Grouping (and in the
 * unassigned bucket). Unlike the report, zero-activity rows are NOT suppressed —
 * the editor must show every Grouping and Category so they can be (re)assigned.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md
 */

import type { Category } from '$lib/types/Category';
import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';

export interface HierarchyGroupNode {
	group: CategoryGroup;
	categories: Category[];
}

export interface HierarchyImportanceNode {
	importance: ImportanceArea;
	groups: HierarchyGroupNode[];
}

export interface HierarchyTree {
	importances: HierarchyImportanceNode[];
	/** Categories with no `group_id` — the editor's "assign me" bucket. */
	unassigned: Category[];
}

const byName = (a: { name: string }, b: { name: string }): number =>
	a.name.localeCompare(b.name);

/**
 * Build the nested Importance → Grouping → Category tree plus the unassigned
 * bucket. Groupings whose `importance_area_id` doesn't resolve to a known
 * Importance are treated as orphaned and folded into a synthetic trailing
 * Importance so their categories are still reachable in the editor (defensive —
 * the FK should prevent this, but the editor must never silently drop a group).
 */
export function buildHierarchyTree(
	importanceAreas: ImportanceArea[],
	groups: CategoryGroup[],
	categories: Category[]
): HierarchyTree {
	// Categories bucketed by their group_id (null → unassigned).
	const categoriesByGroup = new Map<string, Category[]>();
	const unassigned: Category[] = [];
	for (const category of categories) {
		if (!category.group_id) {
			unassigned.push(category);
			continue;
		}
		const bucket = categoriesByGroup.get(category.group_id);
		if (bucket) {
			bucket.push(category);
		} else {
			categoriesByGroup.set(category.group_id, [category]);
		}
	}

	const groupNode = (group: CategoryGroup): HierarchyGroupNode => ({
		group,
		categories: (categoriesByGroup.get(group.id) ?? []).slice().sort(byName)
	});

	const knownImportanceIds = new Set(importanceAreas.map((area) => area.id));
	const groupsByImportance = new Map<string, CategoryGroup[]>();
	const orphanGroups: CategoryGroup[] = [];
	for (const group of groups) {
		if (!knownImportanceIds.has(group.importance_area_id)) {
			orphanGroups.push(group);
			continue;
		}
		const bucket = groupsByImportance.get(group.importance_area_id);
		if (bucket) {
			bucket.push(group);
		} else {
			groupsByImportance.set(group.importance_area_id, [group]);
		}
	}

	const importances: HierarchyImportanceNode[] = importanceAreas
		.slice()
		.sort((a, b) => a.sort_order - b.sort_order)
		.map((importance) => ({
			importance,
			groups: (groupsByImportance.get(importance.id) ?? []).slice().sort(byName).map(groupNode)
		}));

	if (orphanGroups.length > 0) {
		importances.push({
			importance: { id: '', name: 'Unassigned Importance', sort_order: Number.MAX_SAFE_INTEGER },
			groups: orphanGroups.slice().sort(byName).map(groupNode)
		});
	}

	return { importances, unassigned: unassigned.slice().sort(byName) };
}

