import { describe, it, expect } from 'vitest';
import { buildHierarchyTree } from './hierarchyTree';
import type { Category } from '$lib/types/Category';
import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';

// --- fixtures ---------------------------------------------------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-oth', name: 'Other', sort_order: 3 },
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' },
	{ id: 'grp-disc', name: 'Discretionary', importance_area_id: 'imp-oth' }
];

function cat(id: string, name: string, group_id: string | null): Category {
	return { id, name, color: null, group_id };
}

const categories: Category[] = [
	cat('cat-utilities', 'Utilities', 'grp-home'),
	cat('cat-clothes', 'Clothes', 'grp-everyday'),
	cat('cat-groceries', 'Groceries', 'grp-everyday'),
	cat('cat-allowance', 'Allowance', 'grp-kids'),
	cat('cat-alcohol', 'Alcohol', 'grp-disc'),
	cat('cat-orphan-b', 'Widgets', null),
	cat('cat-orphan-a', 'Aardvark', null)
];

describe('buildHierarchyTree', () => {
	it('orders Importance areas by sort_order', () => {
		const tree = buildHierarchyTree(importanceAreas, groups, categories);
		expect(tree.importances.map((i) => i.importance.name)).toEqual([
			'Essential',
			'Priorities',
			'Other'
		]);
	});

	it('orders Groupings alphabetically within an Importance', () => {
		const tree = buildHierarchyTree(importanceAreas, groups, categories);
		const essential = tree.importances.find((i) => i.importance.id === 'imp-ess');
		expect(essential?.groups.map((g) => g.group.name)).toEqual(['Everyday', 'Home']);
	});

	it('nests categories under their group, alphabetically', () => {
		const tree = buildHierarchyTree(importanceAreas, groups, categories);
		const everyday = tree.importances
			.flatMap((i) => i.groups)
			.find((g) => g.group.id === 'grp-everyday');
		expect(everyday?.categories.map((c) => c.name)).toEqual(['Clothes', 'Groceries']);
	});

	it('collects group_id-less categories into unassigned, sorted by name', () => {
		const tree = buildHierarchyTree(importanceAreas, groups, categories);
		expect(tree.unassigned.map((c) => c.name)).toEqual(['Aardvark', 'Widgets']);
	});

	it('renders a Grouping with no categories as an empty node (not suppressed)', () => {
		const emptyGroup: CategoryGroup = {
			id: 'grp-empty',
			name: 'Rental',
			importance_area_id: 'imp-pri'
		};
		const tree = buildHierarchyTree(importanceAreas, [...groups, emptyGroup], categories);
		const rental = tree.importances
			.flatMap((i) => i.groups)
			.find((g) => g.group.id === 'grp-empty');
		expect(rental).toBeDefined();
		expect(rental?.categories).toEqual([]);
	});

	it('renders an Importance area with no groups as an empty node (not suppressed)', () => {
		const extra: ImportanceArea = { id: 'imp-new', name: 'Zeta', sort_order: 4 };
		const tree = buildHierarchyTree([...importanceAreas, extra], groups, categories);
		const zeta = tree.importances.find((i) => i.importance.id === 'imp-new');
		expect(zeta).toBeDefined();
		expect(zeta?.groups).toEqual([]);
	});

	it('folds groups pointing at an unknown Importance into a trailing synthetic node', () => {
		const orphan: CategoryGroup = {
			id: 'grp-orphan',
			name: 'Mystery',
			importance_area_id: 'imp-deleted'
		};
		const tree = buildHierarchyTree(importanceAreas, [...groups, orphan], categories);
		const last = tree.importances[tree.importances.length - 1];
		expect(last.importance.name).toBe('Unassigned Importance');
		expect(last.groups.map((g) => g.group.id)).toContain('grp-orphan');
	});

	it('returns empty structures when there is no hierarchy', () => {
		expect(buildHierarchyTree([], [], [])).toEqual({ importances: [], unassigned: [] });
	});
});

